import psycopg2, psycopg2.extras, os, json, base64, gzip
data = json.loads(gzip.decompress(base64.b64decode("")))
conn = psycopg2.connect(os.environ['DATABASE_URL'], cursor_factory=psycopg2.extras.RealDictCursor)
cur = conn.cursor()
imp = upd = skip = 0
for r in data:
    reg,training,course_type,coaching_method,start_date,end_date,status,attendance,ielts_v,oet_v,plab1_p,plab2_v,other_v,batch_month,batch_year = r
    cur.execute("SELECT registration_number FROM plab_clients WHERE registration_number = %s", (reg,))
    if not cur.fetchone():
        skip += 1; continue
    sd = start_date if start_date else None
    cur.execute("SELECT id FROM ops_coaching WHERE registration_number = %s AND english_training = %s AND (start_date = %s OR (start_date IS NULL AND %s IS NULL))", (reg, training, sd, sd))
    ex = cur.fetchone()
    ed = end_date if end_date else None
    if ex:
        cur.execute("UPDATE ops_coaching SET course_type=%s, coaching_method=%s, coaching_status=%s, attendance=%s, ielts_vendor=%s, oet_vendor=%s, plab1_partner=%s, plab2_vendor=%s, other_vendor=%s, batch_month=%s, batch_year=%s, start_date=%s, end_date=%s WHERE id=%s",
            (course_type, coaching_method, status, attendance, ielts_v, oet_v, plab1_p, plab2_v, other_v, batch_month, batch_year, sd, ed, ex['id']))
        upd += 1
    else:
        cur.execute("INSERT INTO ops_coaching (registration_number, english_training, course_type, coaching_method, coaching_status, attendance, ielts_vendor, oet_vendor, plab1_partner, plab2_vendor, other_vendor, batch_month, batch_year, start_date, end_date, created_by) VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)",
            (reg, training, course_type, coaching_method, status, attendance, ielts_v, oet_v, plab1_p, plab2_v, other_v, batch_month, batch_year, sd, ed, 0))
        imp += 1
conn.commit()
print(f"Coaching: {imp} new, {upd} updated, {skip} skipped")
cur.execute("SELECT COUNT(*) as c FROM ops_coaching"); print("Total coaching:", cur.fetchone()['c'])
conn.close()
